body.tpl-standard { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 10px; color: #1E293B; margin: 0; padding: 12px; background-color: #ffffff; }
.tpl-standard .header-table { width: 100%; border-bottom: 2px solid {{ $accentColor ?: '#1F3864' }}; padding-bottom: 6px; margin-bottom: 15px; }
.tpl-standard .company-name { font-size: 16px; font-weight: 800; color: {{ $accentColor ?: '#1F3864' }}; text-transform: uppercase; }
.tpl-standard .company-address { font-size: 9px; color: #64748B; margin-top: 2px; }
.tpl-standard .payslip-title { font-size: 16px; font-weight: 800; color: {{ $accentColor ?: '#1F3864' }}; text-align: right; text-transform: uppercase; }
.tpl-standard .employee-info-table { width: 100%; background-color: #F8FAFC; border: 1px solid #E2E8F0; border-collapse: collapse; margin-bottom: 15px; }
.tpl-standard .employee-info-table td { padding: 6px 10px; font-size: 10px; }
.tpl-standard .meta-label { color: #64748B; font-weight: 500; }
.tpl-standard .meta-val { font-weight: bold; color: #0F172A; }
.tpl-standard .components-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
.tpl-standard .components-table th { background-color: {{ $accentColor ?: '#1F3864' }}; color: #FFFFFF; padding: 6px; font-size: 10px; text-transform: uppercase; border: 1px solid {{ $accentColor ?: '#1F3864' }}; font-weight: 700; }
.tpl-standard .components-table td { border: 1px solid #E2E8F0; padding: 5px 8px; font-size: 10px; }
.tpl-standard .net-pay-box { background-color: {{ $accentColor ?: '#1F3864' }}; color: #FFFFFF; padding: 10px 15px; margin-bottom: 15px; border-radius: 4px; }
.tpl-standard .net-amount { font-size: 15px; font-weight: bold; color: #FACC15; }
.tpl-standard .net-words { font-size: 10px; font-style: italic; text-align: right; color: #FFFFFF; }
.tpl-standard .footer-note { text-align: center; font-size: 9px; color: #94A3B8; margin-top: 20px; border-top: 1px solid #E2E8F0; padding-top: 8px; }
